-- 事故责任流转（2026-11-22，ADR-0033；契约 plans/incident-responsibility-accept.md）。
-- 设计约束：
--   ① 「转交」是事实，append-only：owner 就地覆盖不足以回答"谁在何时交给谁、为什么"，
--      因此单独建 incident_assignments，禁止用客户端 timeline 充当责任凭证；
--   ② 所有新 SQL 仍带 tenant 条件，tenant 只来自 JWT；
--   ③ 新列只增不改：due_at 可空，sla_state 有默认值 'ok'，旧代码/旧数据照常启动。
-- 自增主键写 IDENTITY 而不是 AUTO_INCREMENT：H2 的 PostgreSQL 兼容模式（测试库）不认
-- AUTO_INCREMENT，而 GENERATED BY DEFAULT AS IDENTITY 在 H2 两种模式与 PostgreSQL 10+ 都成立。
CREATE TABLE IF NOT EXISTS incident_assignments (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    tenant       VARCHAR(64)   NOT NULL,
    incident_id  VARCHAR(64)   NOT NULL,
    from_owner   VARCHAR(64),
    to_owner     VARCHAR(64),
    reason       VARCHAR(200)  NOT NULL,
    assigned_by  VARCHAR(64)   NOT NULL,
    assigned_at  TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_incident_assignments_tenant_incident_at
    ON incident_assignments(tenant, incident_id, assigned_at);

ALTER TABLE incidents ADD COLUMN IF NOT EXISTS due_at TIMESTAMP NULL;
ALTER TABLE incidents ADD COLUMN IF NOT EXISTS sla_state VARCHAR(16) NOT NULL DEFAULT 'ok';
